import{_ as t,o,c as n,a2 as a}from"./chunks/framework.CNDaxUod.js";const c=JSON.parse('{"title":"6. Sign-in: Google, SAML and SCIM","description":"","frontmatter":{},"headers":[],"relativePath":"guide/enterprise-sso.md","filePath":"guide/enterprise-sso.md"}'),s={name:"guide/enterprise-sso.md"};function r(i,e,d,h,g,l){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="_6-sign-in-google-saml-and-scim" tabindex="-1">6. Sign-in: Google, SAML and SCIM <a class="header-anchor" href="#_6-sign-in-google-saml-and-scim" aria-label="Permalink to &quot;6. Sign-in: Google, SAML and SCIM&quot;">​</a></h1><p>Step 6 of the <a href="./getting-started.html">setup path</a>. Until now you have signed in with the operator token. Give your team a real sign-in: Workspace admins get the console, everyone else gets their own page at <code>/app/me</code>.</p><p>Everything on this page ships in the open-source core. There is no paid tier and no SSO tax.</p><table tabindex="0"><thead><tr><th>Method</th><th>Best for</th><th>Admin role comes from</th></tr></thead><tbody><tr><td><strong>Google sign-in</strong></td><td>Google Workspace domains</td><td>The Directory: Workspace super and delegated admins (<a href="./directory.html">step 5</a>)</td></tr><tr><td><strong>SAML</strong></td><td>Any IdP: Google Workspace, Okta, Microsoft Entra, OneLogin</td><td>An IdP group attribute, and the Directory when it&#39;s set up</td></tr><tr><td><strong>Operator token</strong></td><td>The way in before either works, and break-glass after</td><td>Always admin</td></tr></tbody></table><p>You can enable both Google and SAML. The sign-in page shows <strong>Continue with Google</strong>, <strong>Continue with SSO</strong>, and the operator token field while token sign-in is on. AsyncUp refuses any settings change that would leave no working sign-in method.</p><h2 id="google-sign-in" tabindex="-1">Google sign-in <a class="header-anchor" href="#google-sign-in" aria-label="Permalink to &quot;Google sign-in&quot;">​</a></h2><ol><li>In the same Cloud project, <strong>APIs &amp; Services → Credentials → Create credentials → OAuth client ID</strong>, type <strong>Web application</strong>.</li><li>Add the <strong>Authorised redirect URI</strong> <code>https://HOST/auth/callback</code>.</li><li>In AsyncUp, <strong>Settings › Sign-in &amp; SSO → Google sign-in</strong> (or the guided setup&#39;s <strong>Sign-in for your team</strong> step): paste the <strong>OAuth client ID</strong> and <strong>OAuth client secret</strong> and save.</li></ol><p>The consent screen you made Internal in <a href="./google-chat-setup.html">step 2</a> keeps sign-in to your own domain. Chat identity and web identity are the same Google account, so nothing needs linking.</p><p>Without the <a href="./directory.html#admin-role">Directory admin role</a>, everyone who signs in with Google is a regular user and nobody gets the admin console. Use the operator token, or SAML with an admin group, until the role is in place.</p><h2 id="saml-sign-in" tabindex="-1">SAML sign-in <a class="header-anchor" href="#saml-sign-in" aria-label="Permalink to &quot;SAML sign-in&quot;">​</a></h2><p>AsyncUp is a standard SAML 2.0 service provider.</p><table tabindex="0"><thead><tr><th>AsyncUp value</th><th></th></tr></thead><tbody><tr><td>ACS URL</td><td><code>https://HOST/auth/saml/acs</code></td></tr><tr><td>SP entity ID / audience</td><td><code>https://HOST/auth/saml/metadata</code></td></tr><tr><td>Name ID</td><td>The user&#39;s email</td></tr><tr><td>Admin attribute</td><td><code>groups</code> by default</td></tr><tr><td>Admin group</td><td><code>asyncup-admins</code> by default</td></tr></tbody></table><p>AsyncUp needs three values from the IdP: its <strong>entity ID</strong>, its <strong>SSO URL</strong> and its <strong>signing certificate</strong> (PEM). Enter them under <strong>Settings › Sign-in &amp; SSO → SAML single sign-on</strong>, with the admin attribute and group. SP metadata XML is served at <code>https://HOST/auth/saml/metadata</code> for IdPs that import it, but only once those IdP values are saved; before that it answers <code>404</code>.</p><h3 id="google-workspace-as-the-idp" tabindex="-1">Google Workspace as the IdP <a class="header-anchor" href="#google-workspace-as-the-idp" aria-label="Permalink to &quot;Google Workspace as the IdP&quot;">​</a></h3><ol><li><strong>Create the admins group.</strong> Admin console → <strong>Directory → Groups → Create group</strong>. Name it <code>asyncup-admins</code> and add the people who should get the AsyncUp console. Google sends the group&#39;s <em>name</em> in the assertion, so keep it the same as AsyncUp&#39;s <strong>Admin group</strong> value, or change that value to match.</li><li><strong>Create the app.</strong> Admin console → <strong>Apps → Web and mobile apps → Add app → Add custom SAML app</strong>. Name it <em>AsyncUp</em>, continue.</li><li><strong>Copy Google&#39;s IdP details.</strong> The next page shows the <strong>SSO URL</strong>, <strong>Entity ID</strong> and <strong>Certificate</strong>. Copy all three into AsyncUp&#39;s <strong>SAML single sign-on</strong> settings (the certificate including its <code>BEGIN</code> and <code>END</code> lines) and save. Then continue in Google.</li><li><strong>Service provider details.</strong><ul><li>ACS URL: <code>https://HOST/auth/saml/acs</code></li><li>Entity ID: <code>https://HOST/auth/saml/metadata</code></li><li>Name ID format: <strong>EMAIL</strong></li><li>Name ID: <strong>Basic Information › Primary email</strong></li></ul></li><li><strong>Attribute mapping.</strong> Under <strong>Group membership</strong>, pick <code>asyncup-admins</code> and set the app attribute to <code>groups</code>. Finish.</li><li><strong>Turn the app on.</strong> Open the app&#39;s <strong>User access</strong> and set it <strong>ON for everyone</strong>, or for the organisational units that use AsyncUp. Until you do, Google answers sign-in attempts with a <code>403</code> saying the app is not enabled for the user.</li><li><strong>Test</strong> in a private window: <code>https://HOST/app</code> → <strong>Continue with SSO</strong>. Admin console changes can take a few minutes to apply.</li></ol><p><strong>Settings › Sign-in &amp; SSO → Check IdP</strong> confirms the SSO URL answers.</p><h3 id="okta-entra-onelogin" tabindex="-1">Okta, Entra, OneLogin <a class="header-anchor" href="#okta-entra-onelogin" aria-label="Permalink to &quot;Okta, Entra, OneLogin&quot;">​</a></h3><p>Create a SAML 2.0 app with the ACS URL, entity ID and email Name ID above, add a group attribute named <code>groups</code> that carries the admin group, assign the app to your users, and copy the IdP&#39;s entity ID, SSO URL and certificate into AsyncUp.</p><h3 id="who-becomes-an-admin" tabindex="-1">Who becomes an admin <a class="header-anchor" href="#who-becomes-an-admin" aria-label="Permalink to &quot;Who becomes an admin&quot;">​</a></h3><p>Two paths, either one is enough:</p><ol><li><strong>IdP group</strong>: the assertion attribute named by <strong>Admin attribute</strong> (default <code>groups</code>) contains the <strong>Admin group</strong> value (default <code>asyncup-admins</code>). The comparison ignores case and must match a whole value.</li><li><strong>Google Directory</strong>: with the <a href="./directory.html#admin-role">Directory admin role</a> in place, Workspace super and delegated admins are admins, as with Google sign-in.</li></ol><p>Membership: Google sign-in refuses accounts the Directory doesn&#39;t know; SAML deliberately doesn&#39;t, because the IdP vouched for the person and the account may live outside Google (an Okta-only contractor, say). Suspended accounts are refused on both paths.</p><p>Everyone else lands on their personal <a href="./web-app.html">page</a> at <code>/app/me</code>.</p><h3 id="how-saml-users-map-to-chat" tabindex="-1">How SAML users map to Chat <a class="header-anchor" href="#how-saml-users-map-to-chat" aria-label="Permalink to &quot;How SAML users map to Chat&quot;">​</a></h3><p>Standup rosters are keyed by Google Chat user ids. A SAML assertion carries an email, which AsyncUp links to the Chat id through the <a href="./directory.html#user-lookups">Directory</a> on first sign-in, or the first time the person uses the bot. Until then, <code>/app/me</code> shows a &quot;not linked yet&quot; note.</p><h2 id="switch-the-operator-token-off" tabindex="-1">Switch the operator token off <a class="header-anchor" href="#switch-the-operator-token-off" aria-label="Permalink to &quot;Switch the operator token off&quot;">​</a></h2><p>Once Google or SAML works for at least one admin, switch token sign-in off: <strong>Settings › Sign-in &amp; SSO → Setup token → Accept the operator token (OPERATOR_TOKEN) for sign-in</strong>. It covers the token whether you set it as <code>OPERATOR_TOKEN</code> or the older <code>DASHBOARD_TOKEN</code>. The token then stops working for the web app and the JSON API.</p><p>If you lock yourself out later, <a href="./operations.html#locked-out">Operations</a> has the recovery.</p><h2 id="scim-provisioning" tabindex="-1">SCIM provisioning <a class="header-anchor" href="#scim-provisioning" aria-label="Permalink to &quot;SCIM provisioning&quot;">​</a></h2><p>AsyncUp serves a SCIM 2.0 Users endpoint at <code>/scim/v2</code> for IdPs that push provisioning: Okta, Entra, OneLogin.</p><blockquote><p><strong>Google Workspace cannot push SCIM to custom apps</strong> — its auto-provisioning only covers pre-integrated catalogue apps. Pure Google Workspace installs should use the <a href="./directory.html">Directory</a> instead; SCIM is for organisations whose IdP fronts Google.</p></blockquote><p>Setup: generate the <strong>SCIM token</strong> under <strong>Settings › API &amp; tokens → Machine tokens</strong>, then configure your IdP with base URL <code>https://HOST/scim/v2</code> and the token as the bearer credential. Supported: <code>ServiceProviderConfig</code>, list (<code>startIndex</code>/<code>count</code>, max 200), get by id, the <code>userName eq &quot;…&quot;</code> filter (dedupe — other filters answer 501), create, PUT/PATCH updates, deactivate/delete. While no token exists the endpoints answer 404.</p><p>What provisioning does:</p><ul><li><strong>Create/update</strong> registers the user and links them to their Chat identity (through the Directory, by email).</li><li><strong>Deactivate (or delete)</strong> removes the person from <strong>every standup roster</strong> — offboarding in the IdP actually offboards them here.</li><li>Reactivating does not restore rosters; an admin adds them back when they return.</li></ul><p>Adding people to specific standups stays an admin action (the People grid, or <code>add @user</code> in Chat). SCIM has no standup concept, and pushing every provisioned user into every standup would be wrong more often than right.</p>',35)])])}const u=t(s,[["render",r]]);export{c as __pageData,u as default};
